WFJ.Data.add("gossip", {
  ["1200572c30f6818f"] = { "Attenzione! {name} attacca!", "." },
  ["12043cb4af2087c6"] = { "Niente di quello che puoi dire mi porterà mai nell'arena contro quella mostruosità di macchina che chiami carro a vapore!", "." },
  ["12099df54a06cbf6"] = { "Come per la maggior parte degli altri tessuti, le nostre scorte di seta sono ai minimi storici. Le nostre riserve sono tali che da te ci servirebbero in tutto solo sessanta pezze di seta; dovremmo riuscire a raggiungere il nostro obiettivo con il sostegno degli altri.\n\nUn dono generoso come la seta, mi permetto di aggiungere, aumenterebbe di certo la tua reputazione nella comunità! Se hai con te le sessanta pezze di seta e sei <pronto/pronta> a donarle, posso prenderle subito.", "." },
  ["120fab1d77a0c4ad"] = { "Non posso aiutarti con l'addestramento. Dovresti cercarti un istruttore di {class}.", "." },
  ["1210412a5071952d"] = { "Ah sì? Forse dovresti dirmi cos'è che ti turba.", "." },
  ["12130d9bcefb3417"] = { "Ho raggiunto la maestria nella sartoria, Omarion.", "." },
  ["122c0bf9dc67c1ac"] = { "%s mette le spore nei suoi strumenti alchemici...", "." },
  ["123965b9a398c5a2"] = { "Supporto aereo in arrivo a Dun Baldar! Piccatonante, inchinatevi!", "." },
  ["1242fac319dda672"] = { "Il nostro capitano ci salverà!", "." },
  ["12434ec502e3cbf2"] = { "Diciamo che ho l'anima del capitalista, {race}.", "." },
  ["1244792bb300414e"] = { "Perché sire Linguatroce non ha riunito le due parti dello scettro?", "." },
  ["1244a17d086c216c"] = { "Ne ho abbastanza di questi giochi. Procedete, e bandirò le vostre anime nell'oblio!", "." },
  ["124d4b9e03d91e66"] = { "Comandante, è giunto il momento che i cavalieri dei lupi carichino le linee nemiche. Dai l'ordine.", "." },
  ["1257c278d8fcf813"] = { "Mi abbevero della tua sofferenza, mortale. Che la tua essenza si rapprenda con Lokholar!", "." },
  ["125810dbcc88ef84"] = { "Secondo me, i goblin vinceranno a mani basse. Abbiamo gli attrezzi e abbiamo il talento!", "." },
  ["12599922c37ad9ee"] = { "Il Signore del Ghiaccio divorerà l'intero esercito dei Piccatonante!", "." },
  ["125d9480beec8fd2"] = { "Danzeremo sulle vostre ossa!", "." },
  ["1262cd1cbbe26ef4"] = { "Il futuro è nebuloso per voi due. Se lavorerete sulla vostra relazione, di sicuro troverete un po' di felicità.", "." },
  ["1262d6c09e64f930"] = { "Soldati Fontane, MacDugal, Wilcott...", "." },
  ["126c2ca45e70eefb"] = { "La corruzione della Casa dei Nobili ti scorre nelle vene. Lascia che la estirpi con la mia lama!", "." },
  ["127ada4cd3aa3ff6"] = { "Vorrei che la neve si sciogliesse tutta. Mi bagna sempre la veste e mi rovina tutto!", "." },
  ["127b9c587536c55f"] = { "%s emette una risata da rettile... almeno, pensi che sia una risata.", "." },
  ["127bdcde86978459"] = { "I Paragons of Power sono resti dell'antico Impero Gurubashi. Noi Zandalari li cerchiamo: non solo hanno per noi un enorme valore da collezione, ma crediamo anche che custodiscano tracce latenti della magia usata dall'antico Impero.\n\nCon ogni probabilità troverai tre tipi di Paragons a ⟦Zul'Gurub=Zul'gurub⟧: monete, bijou e oggetti primordiali. Portaceli nelle quantità che cerchiamo e riceverai in cambio alcuni dei migliori oggetti che noi Zandalari abbiamo mai creato.", "." },
  ["12812283d15caf51"] = { "C'è una persona le cui conoscenze superano le mie. Sei <pronto/pronta> per andare a cercarla. Vai al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧, nelle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧. Trova Hgarth e prosegui il tuo addestramento.", "." },
  ["128b62c5c1786d70"] = { "Prendi questo segnalatore e avanza verso la base nemica. Raggiungi l'esterno della loro roccaforte principale e piazza il segnalatore al centro del cortile. Difendi il segnalatore dagli assalitori finché l'Occhio non avrà agganciato le sue coordinate.\n\nFatto questo, da qui si potrà osservare tutto ciò che accade fuori dalla base nemica.\n\nTe ne occuperai tu?", "." },
  ["1291b06a1412c441"] = { "Quell'istruttore si trova nella Crafter's Hall, sul lato occidentale di Valanaar.", "." },
  ["12a57a982bf1f1bd"] = { "%s spara d'istinto alle bottiglie...", "." },
  ["12a912c59161c319"] = { "La fine si avvicina rapida! Arrendetevi a Eranikus e sarete risparmiati dalla sofferenza eterna!", "." },
  ["12af60e3a096907c"] = { "Quel bigotto schifoso ha finalmente avuto ciò che si meritava. Che liberazione!", "." },
  ["12bee1b0bfcbaca9"] = { "Finalmente arrivano i soccorsi...", "." },
  ["12e7911a31886398"] = { "Sia chiaro, <pivello/principessina>: non sono in vena di commenti che tu trovi carini o divertenti. Sono qui per assicurarmi che le ricerche dell'Arcidruido procedano come previsto, e ho l'ordine di eliminare tutti gli smidollati che non hanno la stoffa per servire nel mio amato ⟦Cenarion Circle=Circolo Cenariano⟧.", "." },
  ["12e9f5b954eca93a"] = { "Non mi stavi ascoltando? No, dubito fortemente che staremmo facendo questa conversazione se Kel'Thuzad avesse ricomposto il bastone. Kel'Thuzad custodisce la testa. I suoi servitori custodiscono quaranta schegge di Atiesh. L'ultimo pezzo, la base, è stato scoperto da Brann Barbabronzea. L'ultima volta è stato visto nel deserto di ⟦Silithus=Silitus⟧, senza dubbio intento a tenersi il più lontano possibile dagli implacabili cercatori che Kel'Thuzad ha sguinzagliato per il mondo.", "." },
  ["12ec1b310542c3b6"] = { "Quanti dei nostri comandanti sono ancora vivi, Vanndar?", "." },
  ["12eeb2a72a90da43"] = { "Che affari hai con me? Sono un uomo molto impegnato...", "." },
  ["12ef2c39e5ab25e2"] = { "La festa dell'Uomo di Paglia ha inizio! Potere ai Reietti!", "." },
  ["12efc380748aa510"] = { "Dev'essere il tuo giorno fortunato. D'accordo, parlo. Basta che mi lasci in pace. Senti, non mi crederai, ma è stat... oh, Luce, a quanto pare la ragazza sapeva sparare...", "." },
  ["12f169a1239988c5"] = { "Il Frostwolf Relief Hut è stato conquistato dall'⟦Alliance=Alleanza⟧!", "." },
  ["12f5f75fd756a9f1"] = { "Ah! Ho più paura che quei vecchi buchi e squarci facciano scoppiare quell'affare e che mi ritrovi sotto una pioggia di schegge!", "." },
})
